import React, { useState } from 'react';
import Questionnaire from '../components/Questionnaire';
import MovieCard from '../components/MovieCard';

const Home = () => {
    // Yapay zekadan dönecek olan film önerisini tutacağımız State (Durum)
    const [recommendation, setRecommendation] = useState(null);

    return (
        <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'sans-serif' }}>
            <h1 style={{ textAlign: 'center', color: '#2c3e50' }}>🎬 CineSense AI Motoru</h1>
            <p style={{ textAlign: 'center', color: '#7f8c8d', marginBottom: '30px' }}>
                Ruh halini seç, yapay zeka senin için en mükemmel filmi bulsun.
            </p>

            {/* Anket bileşenini çağırıyoruz ve sonucu setRecommendation ile yakalıyoruz */}
            <Questionnaire onRecommendationReceived={(data) => setRecommendation(data)} />

            {/* Eğer recommendation state'i dolduysa (yani cevap geldiyse) Film Kartını ekrana basıyoruz */}
            {recommendation && (
                <div style={{ marginTop: '40px' }}>
                    <h2 style={{ textAlign: 'center', color: '#27ae60' }}>✨ Yapay Zekanın Senin İçin Seçimi ✨</h2>
                    <MovieCard movie={recommendation} />
                </div>
            )}
        </div>
    );
};

export default Home;
